<?php

namespace App\Livewire\Orders;

use App\Enums\OrderStatus;
use App\Livewire\Ordering\Index as OrderingIndex;
use App\Models\Order;
use App\Services\OrderSync;
use App\Services\OrderTelegram;
use App\Support\ShopAccess;
use Illuminate\Support\Facades\Artisan;
use Illuminate\Support\Facades\Gate;
use Livewire\Attributes\Layout;
use Livewire\Component;
use Livewire\WithPagination;

/**
 * Orders from the main warehouse to the shops (drafts are generated by the admin on the Ordering page).
 * A shop's person opens a draft (Show) to edit and confirm it; an admin also confirms older pending orders
 * here and re-queues a failed 1C sync. Operators only see their shops' orders.
 */
#[Layout('components.layouts.app', ['title' => 'Orders'])]
class Index extends Component
{
    use WithPagination;

    public function confirm(int $orderId): void
    {
        $order = $this->find($orderId);
        Gate::authorize('confirm', $order);

        app(OrderSync::class)->confirm($order, auth()->user());
        OrderingIndex::bumpOrdersVersion();
    }

    public function retrySync(int $orderId): void
    {
        $order = $this->find($orderId);
        Gate::authorize('retrySync', $order);

        app(OrderSync::class)->retry($order);
    }

    /** Admin only, drafts only: (re)send each responsible user his personal link; the outcome is stored on the order. */
    public function sendTelegram(int $orderId): void
    {
        Gate::authorize('generate', Order::class);
        $order = $this->find($orderId);
        abort_unless($order->status === OrderStatus::Draft, 404);

        // Same code path as the console command; the outcome is stored on the order.
        Artisan::call('orders:send-telegram', ['order' => $order->id]);
    }

    private function find(int $orderId): Order
    {
        $order = Order::query()->findOrFail($orderId);
        ShopAccess::authorize($order->shop_id);

        return $order;
    }

    public function render()
    {
        $orders = ShopAccess::restrict(Order::query(), 'orders.shop_id')
            ->with('shop')
            ->withCount('items')
            ->latest('id')
            ->paginate(20);

        // Receivers per shop (active operators of the shop with a Telegram chat id): the Send / Resend button only
        // appears for drafts whose shop has at least one.
        $receivers = [];
        foreach (OrderTelegram::responsibleByShop($orders->getCollection()->pluck('shop_id')->unique()->values()->all()) as $shopId => $people) {
            $receivers[$shopId] = $people->filter(fn ($u) => trim((string) $u->telegram_chat_id) !== '')->count();
        }

        return view('livewire.orders.index', [
            'receivers' => $receivers,
            'noShops' => ShopAccess::hasNone(),
            'orders' => $orders,
            'isAdmin' => (bool) auth()->user()?->isAdmin(),
            'onecConfigured' => (string) config('services.onec.orders_url') !== '',
        ]);
    }
}
